sharedTypes.assessment:
export const ASSESSMENT_EVALUATOR_MODULE =
  'src/shared/assessmentEvaluators.ts' as const

export const ASSESSMENT_EVALUATOR_REGISTRY = [
  {
    id: 'EVAL-finite-choice-v1',
    version: 1,
    status: 'stable',
    authorities: ['finite-auto'],
    responseTypes: ['choice'],
    invocation: {
      module: ASSESSMENT_EVALUATOR_MODULE,
      export: 'evaluateAssessment',
      runtime: 'ctx.assessment.evaluate',
    },
  },
  {
    id: 'EVAL-normalized-short-v1',
    version: 1,
    status: 'stable',
    authorities: ['normalized-auto'],
    responseTypes: ['normalized-short'],
    invocation: {
      module: ASSESSMENT_EVALUATOR_MODULE,
      export: 'evaluateAssessment',
      runtime: 'ctx.assessment.evaluate',
    },
  },
] as const

export type AssessmentEvaluatorId =
  typeof ASSESSMENT_EVALUATOR_REGISTRY[number]['id']

export interface AssessmentEvaluationRequest {
  /** Approved response record this invocation implements, when applicable. */
  responseId?: `RESP-${number}`
  evaluatorId: AssessmentEvaluatorId
  input: string
  acceptedValues: readonly string[]
}

export interface AssessmentEvaluationResult {
  evaluatorId: AssessmentEvaluatorId
  normalizedInput: string
  status: 'pass' | 'fail'
}

export const NUMBER_INPUT_REGEX =
  /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/

export function normalizeShortAnswer(value: string): string {
  return value
    .normalize('NFKC')
    .trim()
    .replace(/\s+/gu, ' ')
    .toLocaleLowerCase('und')
}

export function normalizeNumberAnswer(value: string): number | null {
  if (typeof value !== 'string') return null
  const normalized = value.normalize('NFKC').trim()
  if (!NUMBER_INPUT_REGEX.test(normalized)) return null
  const parsed = Number(normalized)
  if (!Number.isFinite(parsed)) return null
  return parsed
}

/**
 * Published, deterministic assessment invocation used by the capability index.
 * The approved case still owns the exact accepted values and tolerance cases.
 */
export function evaluateAssessment(
  request: AssessmentEvaluationRequest,
): AssessmentEvaluationResult {
  if (typeof request?.input !== 'string' ||
      !Array.isArray(request.acceptedValues) ||
      request.acceptedValues.some((value) => typeof value !== 'string')) {
    throw new TypeError('判定请求必须包含字符串 input 与 acceptedValues')
  }
  if (request.responseId !== undefined &&
      (typeof request.responseId !== 'string' ||
        !/^RESP-\d{3,}$/.test(request.responseId))) {
    throw new TypeError('responseId 必须是 RESP-* 稳定 ID')
  }
  const evaluator = ASSESSMENT_EVALUATOR_REGISTRY.find(
    (candidate) => candidate.id === request.evaluatorId,
  )
  if (!evaluator) {
    throw new TypeError(`未发布的判定器：${String(request.evaluatorId)}`)
  }
  const normalize = request.evaluatorId === 'EVAL-normalized-short-v1'
    ? normalizeShortAnswer
    : (value: string) => value.trim()
  const normalizedInput = normalize(request.input)
  const accepted = new Set(request.acceptedValues.map(normalize))
  return {
    evaluatorId: request.evaluatorId,
    normalizedInput,
    status: accepted.has(normalizedInput) ? 'pass' : 'fail',
  }
}

sharedTypes.runtime:
import type * as Phaser from 'phaser'
import type {
  AssessmentEvaluationRequest,
  AssessmentEvaluationResult,
} from '../../assessmentEvaluators'

export type RuntimeApiVersion = 2
export const RUNTIME_RENDER_MODES = ['phaser', 'dom', 'hybrid'] as const
export const RUNTIME_SCOPES = ['scene', 'global'] as const
export const RUNTIME_EXECUTION_MODES = ['preview', 'capture'] as const
export type RuntimeRenderMode = typeof RUNTIME_RENDER_MODES[number]
export type RuntimeLayer = 'underlay' | 'overlay'
export type RuntimeScope = typeof RUNTIME_SCOPES[number]
export type RuntimeExecutionMode = typeof RUNTIME_EXECUTION_MODES[number]
export type RuntimeAuthoringApiVersion = 1

export interface EditableTextMetadata {
  label?: string
  description?: string
  multiline?: boolean
  maxLength?: number
}

export interface EditableTextContent {
  /** Every authored, visible string must be stored here. */
  values: Record<string, string>
  metadata?: Record<string, EditableTextMetadata>
}

export interface RuntimeAssetBinding {
  /** Stable AssetMeta.id from the project asset table. */
  assetId: string
}

export interface RuntimeStaticFallback {
  assetId: string
  coverage: 'runtime-layer' | 'full-scene'
  layer: RuntimeLayer
}

interface RuntimeDocumentBase {
  enabled: boolean
  renderMode: RuntimeRenderMode
  source: string
  content: EditableTextContent
  assets: Record<string, RuntimeAssetBinding>
  /** Semantic binding key -> scene/global node id. Copying a scene rewrites ids. */
  nodeBindings?: Record<string, string>
  staticFallback?: RuntimeStaticFallback
}

export interface RuntimeDocument extends RuntimeDocumentBase {
  runtimeApiVersion: 2
}

export type CourseStateData =
  | null
  | undefined
  | string
  | number
  | boolean
  | bigint
  | CourseStateData[]
  | { [key: string]: CourseStateData }

export interface CourseStateStore {
  get<T = CourseStateData>(key: string): T | undefined
  set(key: string, value: unknown): void
  delete(key: string): void
  clear(): void
  snapshot(): Record<string, unknown>
}

export type RuntimeEventDisposer = () => void
export type RuntimeEventListener<T = unknown> = (
  payload: T,
) => void | Promise<void>

export interface CourseEventBus {
  on<T = unknown>(
    eventName: string,
    listener: RuntimeEventListener<T>,
  ): RuntimeEventDisposer
  off<T = unknown>(eventName: string, listener: RuntimeEventListener<T>): void
  emit<T = unknown>(eventName: string, payload?: T): void
  listenerCount(eventName?: string): number
  dispose(): void
}

export interface RuntimeHostActions {
  /** Published hosts expose continuous steps; feature-detect on older hosts. */
  nextStep?(): boolean
  previousStep?(): boolean
  goToScene(sceneId: string, targetStateId?: string): boolean
  nextScene(): boolean
  previousScene(): boolean
  replayScene(): boolean
  restartCourse(): boolean
}

export interface RuntimeNodeHandle {
  readonly id: string
  readonly type: string
  readonly root: Phaser.GameObjects.GameObject
}

export interface RuntimePresentationStateInfo {
  id: string
  name: string
  description?: string
}

export interface RuntimePresentationTransition {
  /** Duration in milliseconds. Omit or use zero for an immediate switch. */
  duration?: number
  /** Any Phaser tween easing name, for example `Sine.easeInOut`. */
  ease?: string
}

/** Controls declarative, author-editable states of the current scene. */
export interface RuntimePresentationApi {
  current(): string | null
  states(): ReadonlyArray<Readonly<RuntimePresentationStateInfo>>
  setState(stateId: string): boolean
  transitionTo(
    stateId: string,
    transition?: RuntimePresentationTransition,
  ): boolean
}

export interface RuntimePhaserRoots {
  scene: Phaser.Scene
  /** Default root alias. It points to the overlay root. */
  root: Phaser.GameObjects.Container
  underlay: Phaser.GameObjects.Container
  overlay: Phaser.GameObjects.Container
}

export interface RuntimeDomRoots {
  /** Default root alias. It points to the overlay root. */
  root: HTMLElement
  underlay: HTMLElement
  overlay: HTMLElement
}

export interface RuntimeNavigationRequest {
  fromSceneId?: string
  toSceneId: string
}

/** `false` blocks, a scene id redirects, and `true`/`void` allows. */
export type RuntimeNavigationGuardResult = boolean | string | void
export type RuntimeNavigationGuard = (
  request: Readonly<RuntimeNavigationRequest>,
) => RuntimeNavigationGuardResult

export interface RuntimeNavigationApi {
  guard(guard: RuntimeNavigationGuard): RuntimeEventDisposer
}

/** Deterministic, offline evaluators published in the Capability Index. */
export interface RuntimeAssessmentApi {
  evaluate(request: AssessmentEvaluationRequest): AssessmentEvaluationResult
}

export const RUNTIME_EVIDENCE_ACTION_KINDS = [
  'click',
  'select',
  'text-input',
  'formula-input',
  'drag',
  'sort',
  'circle-text',
  'highlight',
  'parameter-change',
  'oral',
  'paper',
  'teacher-command',
] as const

export type RuntimeEvidenceActionKind =
  typeof RUNTIME_EVIDENCE_ACTION_KINDS[number]

export interface RuntimeActionEvidenceRequest {
  actId: `ACT-${number}`
  actionKind: RuntimeEvidenceActionKind
  responseId?: `RESP-${number}`
  /** The native browser event that directly caused this approved action. */
  event: Event
}

/** Records approved actions only when directly caused by a trusted browser event. */
export interface RuntimeEvidenceApi {
  recordAction(request: RuntimeActionEvidenceRequest): void
}

export interface RuntimeContentReader {
  get(key: string): string
  all(): Readonly<Record<string, string>>
}

export interface RuntimeAssetResolver {
  url(bindingKey: string): string
  projectUrl(assetId: string): string
}

export interface RuntimeNodeResolver {
  get(nodeId: string): RuntimeNodeHandle | null
}

export interface RuntimeCaptureContext {
  waitUntil(promise: Promise<unknown>): void
}

export interface RuntimeAuthoringBounds {
  x: number
  y: number
  width: number
  height: number
}

interface RuntimeAuthoringTargetRegistrationBase {
  /** Stable key in RuntimeDocument.content.values or RuntimeDocument.assets. */
  key: string
  /** Optional author-facing label shown by the canvas editor. */
  label?: string
  /** Used only to preserve coarse underlay/overlay hit-test order. */
  layer?: RuntimeLayer
  /**
   * Bounds in the runtime's current logical coordinate system. The host
   * normalizes snapshots to the canonical 1280 x 720 authoring canvas.
   */
  getBounds(): RuntimeAuthoringBounds
}

export interface RuntimeAuthoringTextTargetRegistration
  extends RuntimeAuthoringTargetRegistrationBase {
  kind: 'text'
  multiline?: boolean
  maxLength?: number
}

export interface RuntimeAuthoringAssetTargetRegistration
  extends RuntimeAuthoringTargetRegistrationBase {
  kind: 'asset'
}

export type RuntimeAuthoringTargetRegistration =
  | RuntimeAuthoringTextTargetRegistration
  | RuntimeAuthoringAssetTargetRegistration

/** Optional authoring bridge. It is absent from ordinary preview/capture hosts. */
export interface RuntimeAuthoringApi {
  register(target: RuntimeAuthoringTargetRegistration): RuntimeEventDisposer
  /** Re-measures registered and declarative DOM targets after layout changes. */
  invalidate(): void
}

export type RuntimeAuthoringTargetSource = 'registered' | 'dom'

/** A read-only, session-local target snapshot emitted by an authoring host. */
export interface RuntimeAuthoringTarget {
  /** Stable for the lifetime of the registered region or DOM element. */
  targetId: string
  /**
   * Stable Published layer-item owner. RuntimeHost-local registries omit it;
   * Published surface adapters add it before aggregating multiple carriers.
   */
  nodeId?: string
  scope: RuntimeScope
  sceneId?: string
  kind: 'text' | 'asset'
  key: string
  label?: string
  multiline?: boolean
  maxLength?: number
  layer: RuntimeLayer
  source: RuntimeAuthoringTargetSource
  /** Axis-aligned bounds normalized to the canonical 1280 x 720 canvas. */
  bounds: Readonly<RuntimeAuthoringBounds>
}

export interface RuntimeAuthoringTargetUpdate {
  /** Monotonically increases for each changed snapshot from one host. */
  revision: number
  /** Identifies the host even when cleanup publishes an empty target list. */
  scope: RuntimeScope
  sceneId?: string
  targets: ReadonlyArray<Readonly<RuntimeAuthoringTarget>>
}

export interface RuntimeCreateContextBase {
  scope: RuntimeScope
  mode: RuntimeExecutionMode
  sceneId?: string
  width: number
  height: number

  content: RuntimeContentReader
  assets: RuntimeAssetResolver
  presentation: RuntimePresentationApi
  actions: Readonly<RuntimeHostActions>
  events: CourseEventBus
  localState: CourseStateStore
  courseState: CourseStateStore
  capture: RuntimeCaptureContext
  navigation: RuntimeNavigationApi
  assessment: Readonly<RuntimeAssessmentApi>
  evidence: Readonly<RuntimeEvidenceApi>
  /** Present only when the definition and authoring host both opt into authoring V1. */
  authoring?: RuntimeAuthoringApi
  emit(eventName: string, payload?: unknown): void
}

interface RuntimeCreateContextWithRenderMode extends RuntimeCreateContextBase {
  runtimeApiVersion: 2
  renderMode: RuntimeRenderMode
}

export interface RuntimeCreateContextPhaser
  extends RuntimeCreateContextWithRenderMode {
  renderMode: 'phaser'
  Phaser: typeof Phaser
  phaser: RuntimePhaserRoots
  nodes: RuntimeNodeResolver
}

export interface RuntimeCreateContextDom extends RuntimeCreateContextWithRenderMode {
  renderMode: 'dom'
  domRoot: HTMLElement
  dom: RuntimeDomRoots
}

export interface RuntimeCreateContextHybrid
  extends RuntimeCreateContextWithRenderMode {
  renderMode: 'hybrid'
  Phaser: typeof Phaser
  phaser: RuntimePhaserRoots
  domRoot: HTMLElement
  dom: RuntimeDomRoots
  nodes: RuntimeNodeResolver
}

/** Runtime API 2 exposes only the surfaces declared by RuntimeDocument.renderMode. */
export type RuntimeCreateContext =
  | RuntimeCreateContextPhaser
  | RuntimeCreateContextDom
  | RuntimeCreateContextHybrid

export interface RuntimeInstanceLifecycle {
  resize?(width: number, height: number): void
  setVisible?(visible: boolean): void
  suspend?(): void
  resume?(): void
  prepareCapture?(): void | Promise<void>
  destroy(): void
}

export interface RuntimeDefinition {
  runtimeApiVersion: 2
  /** Optional canvas-authoring extension; versioned independently. */
  authoringApiVersion?: RuntimeAuthoringApiVersion
  create(context: RuntimeCreateContext): RuntimeInstanceLifecycle
}

types:
import type * as Phaser from 'phaser'
import type {
  CourseEventBus,
  CourseStateStore,
  RuntimeCaptureContext,
  RuntimePresentationApi,
} from '../runtime/types'

export type ComponentSchemaVersion = 4
export type ComponentRuntimeApiVersion = 4
export const COMPONENT_SCOPES = ['scene', 'global'] as const
export const COMPONENT_RENDER_MODES = ['phaser', 'dom', 'hybrid'] as const
export const COMPONENT_EXECUTION_MODES = ['edit', 'preview', 'capture'] as const
export type ComponentScope = typeof COMPONENT_SCOPES[number]
export type ComponentRenderMode = typeof COMPONENT_RENDER_MODES[number]
export type ComponentExecutionMode = typeof COMPONENT_EXECUTION_MODES[number]

interface ComponentManifestBase {
  id: string
  name: string
  version: string
  description?: string
  entry: string
  thumbnail?: string
  defaultSize: { width: number; height: number }
  minSize: { width: number; height: number }
  preserveAspectRatio: boolean
  assets: Record<string, string>
  defaultProps: Record<string, unknown>
}

export interface ComponentEditorPropertyBase {
  /** Dot-separated path inside node.props, for example `pages.intro.title`. */
  key: string
  label: string
  description?: string
  required?: boolean
}

export interface ComponentTextProperty extends ComponentEditorPropertyBase {
  type: 'text' | 'textarea'
  placeholder?: string
  maxLength?: number
}

export interface ComponentNumberProperty extends ComponentEditorPropertyBase {
  type: 'number'
  min?: number
  max?: number
  step?: number
  unit?: string
}

export interface ComponentBooleanProperty extends ComponentEditorPropertyBase {
  type: 'boolean'
}

export interface ComponentColorProperty extends ComponentEditorPropertyBase {
  type: 'color'
}

export interface ComponentSelectProperty extends ComponentEditorPropertyBase {
  type: 'select'
  options: Array<{ value: string; label: string }>
}

export interface ComponentImageProperty extends ComponentEditorPropertyBase {
  /** The stored prop value is a project AssetMeta.id. */
  type: 'image'
}

export type ComponentEditorProperty =
  | ComponentTextProperty
  | ComponentNumberProperty
  | ComponentBooleanProperty
  | ComponentColorProperty
  | ComponentSelectProperty
  | ComponentImageProperty

export interface ComponentEditorPage {
  id: string
  label: string
  description?: string
  /** Property keys shown while this internal page is selected in the editor. */
  propertyKeys: string[]
}

export interface ComponentEditorSchema {
  properties: ComponentEditorProperty[]
  /** Optional internal pages used to group fields and preview multi-page components. */
  pages?: ComponentEditorPage[]
  defaultPageId?: string
  /**
   * Prop path used only to persist the editor's currently inspected internal page.
   * A component should use ctx.editorState.pageId in edit mode and keep its playback
   * initial-page prop separate.
   */
  previewPageProp?: string
}

export interface ComponentVariant {
  id: string
  label: string
  description?: string
  /** Props applied when the author switches to this variant. */
  props: Record<string, unknown>
}

export interface ComponentPreset {
  id: string
  label: string
  description?: string
  variantId?: string
  /** Props merged after defaultProps and the referenced variant props. */
  props: Record<string, unknown>
  /** Optional internal page to show immediately after adding the preset. */
  previewPageId?: string
}

export interface ComponentManifestV4 extends ComponentManifestBase {
  schemaVersion: 4
  runtimeApiVersion: 4
  /** V4 components explicitly declare both their mount scopes and render surface. */
  supportedScopes: ComponentScope[]
  renderMode: ComponentRenderMode
  editor?: ComponentEditorSchema
  variants?: ComponentVariant[]
  presets?: ComponentPreset[]
}

/** Current production component contract. */
export type ConfigurableComponentManifest = ComponentManifestV4
export type ComponentManifest = ComponentManifestV4

export interface ComponentHostActions {
  /** Published hosts expose continuous steps; feature-detect on older hosts. */
  nextStep?(): boolean
  previousStep?(): boolean
  goToScene(sceneId: string, targetStateId?: string): boolean
  nextScene(): boolean
  previousScene(): boolean
  replayScene(): boolean
  restartCourse(): boolean
}

export interface ComponentEditorState {
  pageId?: string
  variantId?: string
}

export interface ComponentEditableTextBounds {
  x: number
  y: number
  width: number
  height: number
}

export interface ComponentEditableTextRegion {
  /** Dot-separated path inside node.props, for example `content.title`. */
  key: string
  /** Optional author-facing label shown by the canvas editor. */
  label?: string
  multiline?: boolean
  maxLength?: number
  /**
   * Bounds in the component's authored local coordinate system.
   * A getter lets Phaser components keep the hit target aligned with motion.
   */
  getBounds(): ComponentEditableTextBounds
}

export type ComponentAuthoringTargetSource = 'registered' | 'dom'

/** Explicit component text target measured in the canonical stage space. */
export interface ComponentAuthoringTextTarget {
  kind: 'component-text'
  /** Stable for the lifetime of the registration or DOM element. */
  targetId: string
  scope: ComponentScope
  sceneId?: string
  nodeId: string
  componentId: string
  /** Dot-separated path inside the effective component props. */
  key: string
  label: string
  multiline: boolean
  maxLength?: number
  source: ComponentAuthoringTargetSource
  /**
   * Stage-space rectangle before rotation. Rotate around its center by
   * `rotation` to obtain the visible target in the 1280 x 720 canvas.
   */
  bounds: Readonly<ComponentEditableTextBounds>
  /** Clockwise degrees inherited from the authored component node. */
  rotation: number
}

export interface ComponentAuthoringTargetUpdate {
  revision: number
  /** Identifies the component even when cleanup publishes an empty list. */
  scope: ComponentScope
  sceneId?: string
  nodeId: string
  targets: ReadonlyArray<Readonly<ComponentAuthoringTextTarget>>
}

export interface ComponentEditorHost {
  /**
   * Registers an explicit canvas text-edit hit target. The returned disposer
   * may be called before component destruction when a region is no longer used.
   */
  registerTextRegion(region: ComponentEditableTextRegion): () => void

  /**
   * Requests a recomputation after component-internal layout or motion changes
   * the bounds returned by a registered region. Calls may be coalesced by the
   * host and are safe no-ops after the component authoring host is destroyed.
   */
  invalidate(): void
}

interface ComponentCreateContextV4Base {
  /** Optional role-scoped port; never available to ordinary component instances. */
  teacherController?: import('./teacherController').ComponentTeacherControllerPort
  runtimeApiVersion: 4
  renderMode: ComponentRenderMode
  instanceId: string
  width: number
  height: number
  mode: ComponentExecutionMode
  props: Record<string, unknown>
  editorState: Readonly<ComponentEditorState>
  /** Editor-only optional bridge; absent in preview/capture players. */
  editor?: ComponentEditorHost
  actions: Readonly<ComponentHostActions>
  scope: ComponentScope
  /** Lifecycle-scoped in the player: subscriptions are removed on destroy. */
  events?: CourseEventBus
  /** Shared across ordinary scene navigation and reset by restartCourse(). */
  courseState?: CourseStateStore
  /** Player-only declarative scene-state controller. */
  presentation?: RuntimePresentationApi
  /** Lets async assets participate in deterministic thumbnail/export capture. */
  capture: RuntimeCaptureContext
  assetUrl(assetKey: string): string
  projectAssetUrl(assetId: string): string
  emit(eventName: string, payload?: unknown): void
}

export interface ComponentPhaserSurface {
  Phaser: typeof Phaser
  scene: Phaser.Scene
  root: Phaser.GameObjects.Container
}

export interface ComponentDomSurface {
  root: HTMLElement
}

export interface ComponentCreateContextV4Phaser
  extends ComponentCreateContextV4Base {
  renderMode: 'phaser'
  phaser: ComponentPhaserSurface
}

export interface ComponentCreateContextV4Dom
  extends ComponentCreateContextV4Base {
  renderMode: 'dom'
  dom: ComponentDomSurface
}

export interface ComponentCreateContextV4Hybrid
  extends ComponentCreateContextV4Base {
  renderMode: 'hybrid'
  phaser: ComponentPhaserSurface
  dom: ComponentDomSurface
}

/**
 * V4 exposes only the renderer capabilities declared by manifest.renderMode.
 * Renderer roots are nested so DOM and Phaser never share an ambiguous `root`.
 */
export type ComponentCreateContextV4 =
  | ComponentCreateContextV4Phaser
  | ComponentCreateContextV4Dom
  | ComponentCreateContextV4Hybrid

export interface ComponentInstanceLifecycle {
  setMode?(mode: ComponentExecutionMode): void
  resize?(width: number, height: number): void
  updateProps?(props: Record<string, unknown>): void
  setEditorState?(state: Readonly<ComponentEditorState>): void
  setVisible?(visible: boolean): void
  suspend?(): void
  resume?(): void
  prepareCapture?(): void | Promise<void>
  destroy(): void
}

export interface ComponentDefinitionV4 {
  id: string
  runtimeApiVersion: 4
  create(context: ComponentCreateContextV4): ComponentInstanceLifecycle
}

export interface EmbeddedComponentPackageMeta {
  packageId: string
  version: string
  name: string
  manifestPath: string
  runtimePath: string
  thumbnailPath?: string
  /** Canonical SHA-256 of all embedded component paths and bytes. */
  contentSha256: string
  /** SHA-256 of the exact .h5component bytes selected from a catalog or file. */
  sha256?: string
  /** ISO timestamp recorded when the executable package entered this project. */
  importedAt?: string
  /** Human-readable catalog/source label; never an external absolute path. */
  sourceLabel?: string
  /** Explicit authoring provenance; imported third-party packages default to read-only. */
  editableCopy?: boolean
  sourcePackageId?: string
}

export interface ComponentPackageData {
  manifest: ComponentManifest
  runtimeSource: string
  files: Record<string, Uint8Array>
  /** Recomputed by package parsing; raw test/build sources may omit the cache. */
  readonly contentSha256?: string
  thumbnailUrl?: string
  /** Import provenance used to lock exact executable bytes in the current project. */
  provenance?: {
    sha256: string
    importedAt: string
    sourceLabel: string
  }
}
